params.command:
$ErrorActionPreference='Stop';
Write-Output ('HEAD='+(git rev-parse HEAD));
Write-Output '===STATUS==='; git status --short --branch;
Write-Output '===SERVER-HEAD==='; Get-Content 'tools\agent-control\server.mjs' -TotalCount 140;
Write-Output '===PLACEMENT-DEPLOY==='; $x=Get-Content 'tools\agent-control\server.mjs'; $x[540..970];
Write-Output '===TOP-IMPORTS-CONSTANTS==='; $x[0..180];
Write-Output '===CONTROL-CORE-POLICY==='; Select-String -Path 'tools\agent-control\lib\control-core.mjs' -Pattern 'canUseMachineForRepositoryWrite|integrationEligibility|isIntegration|machinePolicies' -Context 8,18;
Write-Output '===AUTOPILOT-STEPS==='; Select-String -Path 'tools\agent-control\lib\autopilot-core.mjs' -Pattern 'machine|implementation|verification|review|repair' -Context 5,10;
Write-Output '===TEST-SAFETY-TAIL==='; Get-Content 'tools\agent-control\test\server-safety.test.mjs' -Tail 260;
Write-Output '===PACKAGE==='; Get-Content 'tools\agent-control\package.json';
Write-Output '===README-PROVIDER-HITS==='; Select-String -Path 'tools\agent-control\README.md','tools\agent-control\CONTROL_PLANE.md' -Pattern 'worker|heaven|machine|provider|Codex' -Context 2,3 | Select-Object -First 120;
